// ============================================
// UNIVERSAL PACKET DECODER v2.0
// Unisce:
// - ACK binario + Telegram alarms (nodo1)
// - Decodifica dichiarativa via PARSER_SPECS (nodo2)
// - Gestione METEO multi-record + version check
// ============================================

// ─── Costanti dalle globali ──────────────────────────────────────────────
const PROTO = global.get("PROTO");
const SCALING = global.get("SCALING");
const TYPES = global.get("TYPES");
const DEVICES = global.get("DEVICES");
const ACK_STATES = global.get("ACK_STATES");
const PARSER_SPECS = global.get("PARSER_SPECS");
const DEVICE_NAME_MAP = global.get("DEVICE_NAME_MAP");
const TYPE_NAME_MAP = global.get("TYPE_NAME_MAP");

// Fallback per compatibilità
const PKT_MAGIC = PROTO?.MAGIC ?? 170;
const PKT_VERSION = PROTO?.VERSION ?? 2;
const HEADER_SIZE = PROTO?.HEADER_SIZE ?? 5;
const PACKET_MIN_SIZE = PROTO?.MIN_SIZE ?? 6;

const ACK_OK = ACK_STATES?.ACK_OK ?? 1;
const ACK_END = ACK_STATES?.ACK_END ?? 2;
const ACK_FAILED = ACK_STATES?.ACK_FAILED ?? 3;
const ACK_ERROR = ACK_STATES?.ACK_ERROR ?? 4;

const TYPE_ACK = TYPES?.ACK ?? 0;
const TYPE_METEO = TYPES?.METEO ?? 3;

const DEV_MASTER = DEVICES?.NODE_RED ?? 255;
const TELEGRAM_CHAT_ID = -1001197831676;  // fisso dal tuo codice

// ─── Helper: Validazione XOR ────────────────────────────────────────────
function validateXOR(buffer) {
    let xor = 0;
    for (let i = 0; i < buffer.length - 1; i++) xor ^= buffer[i];
    return xor === buffer[buffer.length - 1];
}

// ─── Helper: Build ACK binario (v2.1 con cmdEcho/valEcho) ───────────────
function buildBinaryAck(targetDeviceId, status, cmdEcho = 0, valEcho = 0) {
    const frame = Buffer.alloc(HEADER_SIZE + 4 + 1);
    frame[0] = PKT_MAGIC;
    frame[1] = PKT_VERSION;
    frame[2] = TYPE_ACK;
    frame.writeUInt16LE(4, 3);        // payload length = 4
    frame[5] = targetDeviceId;
    frame[6] = status;
    frame[7] = cmdEcho;
    frame[8] = valEcho;

    let xor = 0;
    for (let i = 0; i < frame.length - 1; i++) xor ^= frame[i];
    frame[frame.length - 1] = xor;
    return frame;
}

// ─── Helper: Decodifica dichiarativa via PARSER_SPECS ───────────────────
function decodeBySpec(buffer, packetType) {
    const typeKey = `TYPE_${packetType}`;
    const typeSpec = PARSER_SPECS?.[typeKey];

    if (!typeSpec) {
        return { error: `No spec for ${typeKey}`, decoded: null };
    }

    const fields = typeSpec.fields || typeSpec;
    const result = {};

    for (const field of fields) {
        if (field.offset >= buffer.length) {
            result[field.name] = null;
            continue;
        }

        let value;
        try {
            switch (field.type) {
                case "uint8":    value = buffer.readUInt8(field.offset); break;
                case "uint16le": value = buffer.readUInt16LE(field.offset); break;
                case "uint16be": value = buffer.readUInt16BE(field.offset); break;
                case "int16le":  value = buffer.readInt16LE(field.offset); break;
                case "int16be":  value = buffer.readInt16BE(field.offset); break;
                case "uint32le": value = buffer.readUInt32LE(field.offset); break;
                case "int32le":  value = buffer.readInt32LE(field.offset); break;
                case "floatle":  value = buffer.readFloatLE(field.offset); break;
                case "floatbe":  value = buffer.readFloatBE(field.offset); break;
                default:
                    node.warn(`Tipo non gestito: ${field.type} per ${field.name}`);
                    continue;
            }
        } catch(e) {
            node.warn(`Lettura fallita ${field.name}: ${e.message}`);
            result[field.name] = null;
            continue;
        }

        // Scaling
        if (field.div !== undefined && value !== null) value = value / field.div;
        if (field.sub !== undefined && value !== null) value = value - field.sub;

        // Arrotonda a 2 decimali
        if (typeof value === "number" && !Number.isInteger(value)) {
            value = Math.round(value * 100) / 100;
        }

        result[field.name] = value;
    }

    return { error: null, decoded: result };
}

// ─── Helper: Invia allarme Telegram ─────────────────────────────────────
function sendTelegramAlert(message) {
    return {
        payload: {
            chatId: TELEGRAM_CHAT_ID,
            type: 'message',
            content: message
        }
    };
}

// ─── Helper: Comfort decoder per DHT (opzionale, se non in spec) ────────
function decodeComfort(bitmask) {
    return {
        ok: (bitmask & 1) !== 0,
        tooHot: (bitmask & 2) !== 0,
        tooCold: (bitmask & 4) !== 0,
        tooDry: (bitmask & 8) !== 0,
        tooHumid: (bitmask & 16) !== 0
    };
}

// ─── Helper: Verifica se il pacchetto è METEO multi-record (66 byte) ────
function isMultiMeteoPacket(fullBuffer, payloadLength) {
    const type = fullBuffer[2];
    return type === TYPE_METEO && payloadLength === 66;
}

// ─── Helper: Ottiene nome dispositivo ───────────────────────────────────
function getDeviceName(deviceId) {
    if (DEVICE_NAME_MAP && DEVICE_NAME_MAP[deviceId]) {
        return DEVICE_NAME_MAP[deviceId];
    }
    // Cerca nel reverse di DEVICES
    for (const [name, id] of Object.entries(DEVICES || {})) {
        if (id === deviceId) return name;
    }
    return `0x${deviceId.toString(16).toUpperCase()}`;
}

// ============================================
// MAIN
// ============================================

const fullBuffer = msg.payload;
let alarmMsg = null;
let ackMsg = null;

// ─── 1. Validazione base ────────────────────────────────────────────────
if (!Buffer.isBuffer(fullBuffer) || fullBuffer.length < PACKET_MIN_SIZE) {
    node.error("Pacchetto troppo piccolo o non Buffer");
    return [null, sendTelegramAlert("❌ ERRORE: Pacchetto malformato (size < MIN_SIZE)"), null];
}

if (fullBuffer[0] !== PKT_MAGIC) {
    node.error("Magic byte errato");
    return [null, sendTelegramAlert(`❌ ERRORE: Magic byte errato (0x${fullBuffer[0].toString(16)})`), null];
}

// ─── 2. Validazione XOR ─────────────────────────────────────────────────
if (!msg.xorValidated && !validateXOR(fullBuffer)) {
    node.error("Checksum XOR fallito");
    alarmMsg = sendTelegramAlert("⚠️ CHECKSUM XOR FALLITO - Pacchetto corrotto");
    const deviceId = fullBuffer[HEADER_SIZE] || 0;
    ackMsg = buildBinaryAck(deviceId, ACK_ERROR);
    return [null, alarmMsg, ackMsg];
}

// ─── 3. Estrai metadati base ───────────────────────────────────────────
const type = fullBuffer[2];
const protocolVersion = fullBuffer[1];
const payloadLength = fullBuffer.readUInt16LE(3);
const payloadBuffer = fullBuffer.slice(HEADER_SIZE, fullBuffer.length - 1);
const deviceId = payloadBuffer[0] || 0;
const deviceName = getDeviceName(deviceId);

// ─── 4. Verifica versione protocollo (warning) ─────────────────────────
if (protocolVersion < PKT_VERSION) {
    const warningMsg = `⚠️ ATTENZIONE: Device ${deviceName} (0x${deviceId.toString(16)}) usa protocollo OBSOLETO v${protocolVersion} (richiesta v${PKT_VERSION})`;
    node.warn(warningMsg);
    alarmMsg = sendTelegramAlert(warningMsg);
    // Non blocchiamo, ma segnaliamo
}

// ─── 5. Gestione speciale: METEO multi-record (66 byte) ────────────────
if (isMultiMeteoPacket(fullBuffer, payloadLength)) {
    node.debug(`METEO multi-packet da ${deviceName} - inoltro a parser specializzato`);
    msg.topic = "meteo/multi";
    msg.rawBuffer = fullBuffer;  // preserva per parsing successivo
    return [msg, alarmMsg, null];  // niente ACK qui, lo farà il parser multi
}

// ─── 6. Decodifica standard via PARSER_SPECS ───────────────────────────
const { error, decoded } = decodeBySpec(payloadBuffer, type);

if (error) {
    node.warn(`Tipo sconosciuto: 0x${type.toString(16)} da ${deviceName}`);
    ackMsg = buildBinaryAck(deviceId, ACK_ERROR);
    return [null, alarmMsg, ackMsg];
}

// ─── 7. Arricchisci output con comfort per DHT (se presente e non già espanso)
let finalPayload = decoded;
if (type === TYPES?.DHT && decoded.comfort !== undefined && typeof decoded.comfort === 'number') {
    finalPayload = {
        ...decoded,
        comfortFlags: decodeComfort(decoded.comfort),
        comfortText: Object.entries(decodeComfort(decoded.comfort))
            .filter(([,v]) => v).map(([k]) => k).join(', ') || 'ok'
    };
}

// ─── 8. Determina topic di output ──────────────────────────────────────
let targetTopic = `sensors/${TYPE_NAME_MAP?.[type] || type}`;
// Override per alcuni tipi
if (type === TYPE_ACK) targetTopic = "system/ack";
if (type === TYPES?.ANNOUNCE) targetTopic = "system/announce";
if (type === TYPES?.COMMAND) targetTopic = "commands/received";
if (type === TYPES?.TIME) targetTopic = "system/time";
if (type === TYPES?.PID_CONFIG) targetTopic = "sensors/caminetto/config";
if (type === TYPES?.TENDE_COMMAND) targetTopic = "commands/tende";

// ─── 9. Costruisci ACK (solo per tipi che lo richiedono) ───────────────
const typesNeedingAck = [
    TYPES?.METEO, TYPES?.TENDE, TYPES?.CAMINETTO, 
    TYPES?.PID_CONFIG, TYPES?.TENDE_COMMAND
];
const needsAck = typesNeedingAck.includes(type);
if (needsAck && type !== TYPE_ACK) {
    ackMsg = buildBinaryAck(deviceId, ACK_END);
}

// ─── 10. Output finale ─────────────────────────────────────────────────
msg.payload = finalPayload;
msg.topic = targetTopic;
msg.packetMeta = {
    typeKey: `TYPE_${type}`,
    typeName: TYPE_NAME_MAP?.[type] || `0x${type.toString(16)}`,
    typeNumber: type,
    deviceId: deviceId,
    deviceName: deviceName,
    protocolVersion: protocolVersion,
    rawLen: fullBuffer.length,
    payloadLen: payloadLength,
    xorValid: true
};

node.status({
    fill: "green",
    shape: "dot",
    text: `${msg.packetMeta.typeName} | ${deviceName}`
});

return [msg, alarmMsg, ackMsg];
